"""Reproduce the user-authorized EP08/EP09 sound pass from saved cue choices."""
import sys,json,hashlib
from pathlib import Path
R=Path(__file__).resolve().parents[2];sys.path.insert(0,str(R/'tools/storytime'))
from sfx_levels import pcm,choose_gain
from audio_mix import calibrate_mix
cat={a['id']:a for a in json.loads((R/'common/audio/sfx/sfx_catalog.json').read_text())['assets']}
def write(p,s):p.write_text(json.dumps(s,indent=2)+'\n')
def prepare(voice,id,at,dur,role):
 a=cat[id];assert a['commercial_use'] and (R/a['relative_path']).is_file()
 dur=min(dur,a['duration_seconds']);g,m=choose_gain(R/a['relative_path'],voice,at,dur,role)
 return a,round(dur,6),g,m
