s['mix']=calibrate_mix(s,R);write(p/'scene.json',s)
write(p/'sound_plan.json',{'voice_sha256':hashlib.sha256((R/s['audio'].removeprefix('res://')).read_bytes()).hexdigest(),'notes':'Original narration and picture clock. Crying and post-payoff holds deliberately quiet. Familiar catalog sound types, no borrowed vocal memes.','events':notes})
print('Sound cues: EP08',len(plan['events']),'EP09',len(notes))
for label,events in [('EP08',plan['events']),('EP09',notes)]:
 print(label,'quiet cues',[(e['sfx_id'],e['levels']['relative_rms_db']) for e in events if e['levels']['relative_rms_db'] < -18])
